def girth(n, adj):
    g=10**9
    cyc=None
    for s in range(n):
        dist=[-1]*n; par=[-1]*n
        q=deque([s]); dist[s]=0
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    if dist[u]+dist[v]+1<g:
                        g=dist[u]+dist[v]+1; cyc=(u,v,s,dist[u],dist[v])
    return g,cyc
print('girth', girth(n,adj))
